<?php
declare(strict_types=1);
const CTRL_VER='1.0.0';
const CFG='/etc/xlx026-control/config.php';
const STATE='/var/lib/xlx026-control';
const HELPER='/usr/local/sbin/xlx026-control-helper';
const BASE='https://xlx026.net';

header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet');
header('X-Frame-Options: DENY');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: no-referrer');
header("Content-Security-Policy: default-src 'self'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'");
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
if(!is_file(CFG)){http_response_code(503);exit('Controle XLX026 indisponível.');}
$cfg=require CFG;
foreach(['username','password_hash','expected_core_sha','expected_core_version'] as $k){if(empty($cfg[$k])||!is_string($cfg[$k])){http_response_code(503);exit('Configuração inválida.');}}

session_name('XLX026CTRL');
session_set_cookie_params(['lifetime'=>0,'path'=>'/controle/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);
ini_set('session.use_strict_mode','1'); ini_set('session.use_only_cookies','1'); session_start();
function h(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ip():string{return $_SERVER['REMOTE_ADDR']??'unknown';}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return (string)$_SESSION['csrf'];}
function csrf_ok(string $v):bool{return isset($_SESSION['csrf'])&&hash_equals((string)$_SESSION['csrf'],$v);}
function auth():bool{if(($_SESSION['auth']??false)!==true)return false;$n=time();$l=(int)($_SESSION['last']??0);$b=(int)($_SESSION['born']??0);if(!$l||!$b||$n-$l>1200||$n-$b>28800){$_SESSION=[];session_destroy();return false;}$_SESSION['last']=$n;return true;}
function audit(string $e):void{@file_put_contents(STATE.'/audit.log',date('c').' ip='.ip().' event='.preg_replace('/[^A-Za-z0-9_.:-]/','_',$e)."\n",FILE_APPEND|LOCK_EX);}
function ratefile():string{return STATE.'/login-'.hash('sha256',ip()).'.json';}
function rate():array{$f=ratefile();$d=is_file($f)?json_decode((string)@file_get_contents($f),true):null;return is_array($d)?$d:['fails'=>0,'first'=>0,'locked'=>0];}
function fail_login():void{$s=rate();$n=time();if(empty($s['first'])||$n-(int)$s['first']>900)$s=['fails'=>0,'first'=>$n,'locked'=>0];$s['fails']=(int)$s['fails']+1;if($s['fails']>=5)$s['locked']=$n+900;@file_put_contents(ratefile(),json_encode($s),LOCK_EX);}
function runh(string $c):array{$a=['status','listeners','logs','backups','restart'];if(!in_array($c,$a,true))return[false,'',64];$o=[];$r=0;exec('/usr/bin/sudo -n '.escapeshellarg(HELPER).' '.escapeshellarg($c).' 2>&1',$o,$r);return[$r===0,implode("\n",$o),$r];}
function kv(string $s):array{$r=[];foreach(preg_split('/\R/',$s)?:[] as $l){if(str_contains($l,'=')){[$k,$v]=explode('=',$l,2);$r[trim($k)]=trim($v);}}return$r;}
function probe(string $url):array{$o=[];$r=0;exec('/usr/bin/curl --silent --show-error --location --connect-timeout 4 --max-time 8 --output - --write-out '.escapeshellarg("\n__C__:%{http_code}").' '.escapeshellarg($url).' 2>&1',$o,$r);$x=implode("\n",$o);$c=0;if(preg_match('/\n__C__:(\d{3})\s*$/',$x,$m)){$c=(int)$m[1];$x=preg_replace('/\n__C__:\d{3}\s*$/','',$x)??$x;}return[$c,$x,$r];}

$msg='';$bad=false;$tests=[];$restart='';
if(isset($_GET['logout'])){audit('logout');$_SESSION=[];session_destroy();header('Location:/controle/');exit;}
if(!auth()){
 if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='login'){
  $s=rate();$left=max(0,(int)($s['locked']??0)-time());
  if($left){$msg="Muitas tentativas. Aguarde {$left}s.";$bad=true;}
  else{$u=(string)($_POST['username']??'');$p=(string)($_POST['password']??'');if(hash_equals($cfg['username'],$u)&&password_verify($p,$cfg['password_hash'])){@unlink(ratefile());session_regenerate_id(true);$_SESSION=['auth'=>true,'born'=>time(),'last'=>time(),'csrf'=>bin2hex(random_bytes(32))];audit('login_ok');header('Location:/controle/');exit;}fail_login();usleep(500000);audit('login_fail');$msg='Usuário ou senha inválidos.';$bad=true;}
 }
 ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Controle XLX026</title><style>body{margin:0;background:#07111f;color:#e8f0ff;font:16px system-ui;display:grid;min-height:100vh;place-items:center}.b{width:min(92vw,430px);background:#0d1b2e;border:1px solid #294a74;border-radius:18px;padding:28px}.t{font-size:27px;font-weight:800}.m{color:#9fb3cf;margin:7px 0 22px}label{display:block;margin-top:13px}input{width:100%;box-sizing:border-box;padding:12px;margin-top:5px;border-radius:9px;border:1px solid #37577f;background:#07111f;color:#fff}button{width:100%;padding:12px;margin-top:18px;border:0;border-radius:9px;background:#1f6feb;color:#fff;font-weight:800}.e{padding:10px;background:#4b1d25;border-radius:8px}</style></head><body><main class="b"><div class="t">Controle XLX026</div><div class="m">Acesso restrito</div><?php if($msg):?><div class="e"><?=h($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="action" value="login"><label>Usuário</label><input name="username" autocomplete="username" required autofocus><label>Senha</label><input type="password" name="password" autocomplete="current-password" required><button>Entrar</button></form><div class="m" style="margin-top:18px">XLX Modern · Controle v<?=h(CTRL_VER)?></div></main></body></html><?php exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_ok((string)($_POST['csrf']??''))){http_response_code(400);audit('csrf_fail');exit('Requisição inválida.');}
 $a=(string)($_POST['action']??'');
 if($a==='tests'){$tg=[['/ao-vivo',200,'h'],['/conectados',200,'h'],['/suporte',200,'h'],['/aprs-dprs',200,'h'],['/ranking',200,'h'],['/certificado',200,'h'],['/simulado-anatel/',200,'h'],['/refletores',200,'h'],['/noticias',200,'h'],['/api/status.php',200,'j'],['/api/live.php',200,'j'],['/api/mtr.php',400,'j']];foreach($tg as[$p,$e,$k]){[$c,$b]=probe(BASE.$p);$ok=$c===$e&&($k==='h'||is_array(json_decode($b,true)));$tests[]=[$p,$c,$e,$ok];}audit('tests');}
 if($a==='restart'){$p=(string)($_POST['restart_password']??'');$c=($_POST['confirm_restart']??'')==='yes';if(!$c||!password_verify($p,$cfg['password_hash'])){$msg='Reinício cancelado: confirmação ou senha inválida.';$bad=true;audit('restart_denied');}else{[$ok,$restart]=runh('restart');$msg=$ok?'XLXD reiniciado e validado com sucesso.':'Falha no reinício/validação.';$bad=!$ok;audit($ok?'restart_ok':'restart_fail');}}
}
[$ok,$st]=runh('status');$s=kv($st);[$code,$body]=probe(BASE.'/api/status.php?history_hours=24&control=1');$api=json_decode($body,true);if(!is_array($api))$api=[];[, $listeners]=runh('listeners');[, $logs]=runh('logs');[, $backups]=runh('backups');$token=csrf();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Controle XLX026</title><style>*{box-sizing:border-box}body{margin:0;background:#07111f;color:#e8f0ff;font:15px system-ui}.w{max-width:1180px;margin:auto;padding:20px}.top{display:flex;justify-content:space-between;align-items:center}.title{font-size:28px;font-weight:850}.muted{color:#8fa6c4}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-top:18px}.c,.p{background:#0d1b2e;border:1px solid #27466f;border-radius:14px}.c{padding:15px}.v{font-size:22px;font-weight:850;margin-top:5px}.ok{color:#54d98c}.bad{color:#ff7a88}.p{padding:18px;margin-top:14px}.p h2{margin:0 0 12px;font-size:18px}button,.btn{padding:10px 14px;border:0;border-radius:9px;background:#1f6feb;color:white;font-weight:750;text-decoration:none;cursor:pointer}.danger{background:#a83243}pre{white-space:pre-wrap;word-break:break-word;background:#07111f;border:1px solid #203a5f;border-radius:9px;padding:11px;max-height:300px;overflow:auto}.msg{padding:10px;border-radius:9px;background:#123622}.msg.bad{background:#4b1d25}.actions{display:flex;gap:10px;flex-wrap:wrap}table{width:100%;border-collapse:collapse}td,th{padding:7px;border-bottom:1px solid #203a5f;text-align:left}.restart input[type=password]{padding:10px;background:#07111f;color:#fff;border:1px solid #37577f;border-radius:8px}.logout{color:#c8daf3}.foot{text-align:center;color:#7188a6;margin:20px}</style></head><body><div class="w"><div class="top"><div><div class="title">Controle XLX026</div><div class="muted">Área técnica privada</div></div><a class="logout" href="?logout=1">Sair</a></div><?php if($msg):?><div class="msg <?=$bad?'bad':''?>"><?=h($msg)?></div><?php endif;?><div class="grid"><div class="c"><div class="muted">XLXD</div><div class="v <?=($s['service']??'')==='active'?'ok':'bad'?>"><?=h($s['service']??'?')?></div></div><div class="c"><div class="muted">Core</div><div class="v"><?=h($s['version']??'?')?></div></div><div class="c"><div class="muted">PID</div><div class="v"><?=h($s['pid']??'?')?></div></div><div class="c"><div class="muted">Processos</div><div class="v"><?=h($s['processes']??'?')?></div></div><div class="c"><div class="muted">Conectados</div><div class="v"><?=h((string)($api['connected_count']??'?'))?></div></div><div class="c"><div class="muted">TX ativa</div><div class="v"><?=h((string)($api['active_count']??'?'))?></div></div></div><section class="p"><h2>Integridade e testes</h2><pre><?=h($s['sha']??'?')?></pre><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=h($token)?>"><input type="hidden" name="action" value="tests"><button>Executar testes gerais</button></form><a class="btn" href="/controle/">Atualizar</a></div><?php if($tests):?><table><tr><th>Teste</th><th>HTTP</th><th>Esperado</th><th>Resultado</th></tr><?php foreach($tests as[$p,$c,$e,$o]):?><tr><td><?=h($p)?></td><td><?=$c?></td><td><?=$e?></td><td class="<?=$o?'ok':'bad'?>"><?=$o?'OK':'FALHOU'?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="p"><h2>Listeners UDP</h2><pre><?=h($listeners)?></pre></section><section class="p"><h2>Logs recentes</h2><pre><?=h($logs)?></pre></section><section class="p"><h2>Backups recentes</h2><pre><?=h($backups)?></pre></section><section class="p"><h2>Reiniciar XLXD</h2><p class="muted">Reinicia somente xlxd.service e valida versão, SHA e processo depois.</p><form method="post" class="restart"><input type="hidden" name="csrf" value="<?=h($token)?>"><input type="hidden" name="action" value="restart"><input type="password" name="restart_password" placeholder="Confirme sua senha" required> <button class="danger">Reiniciar XLXD</button><p><label><input type="checkbox" name="confirm_restart" value="yes" required> Confirmo o reinício somente do XLXD.</label></p></form><?php if($restart):?><pre><?=h($restart)?></pre><?php endif;?></section><div class="foot">XLX Modern · Controle v<?=h(CTRL_VER)?> · não indexado</div></div></body></html>
